    if (result != noErr) {
        if (outError != NULL) {
            *outError = [NSError errorWithDomain:NSOSStatusErrorDomain
                                            code:result
                                        userInfo:@{NSLocalizedDescriptionKey: @"Failed to allocate Rust render resources"}];
        }
        [super deallocateRenderResources];
        return NO;
    }

    _resourcesAllocated = YES;
    return YES;
}

