    _inputMutableABL = NULL;
    _inputPCMBuffer = nil;
    _hostMusicalContext = nil;
    _hostTransportState = nil;
    _hostMidiOutput = nil;

    if (_rustInstance != NULL && _resourcesAllocated) {
        beamer_au_deallocate_render_resources(_rustInstance);
        _resourcesAllocated = NO;
