            }

            AudioUnitRenderActionFlags pullFlags = 0;
            AUAudioUnitStatus pullStatus = pullInputBlock(&pullFlags, timestamp, frameCount, 0, inputMutableABL);
            if (pullStatus == noErr) {
                inputData = inputMutableABL;
            }
        }

        // Only the render of the main bus processes audio and needs the transport.
        BeamerAuTransport transport;
        BOOL hasTransport = (outputBusNumber == 0);
        if (hasTransport) {
            BeamerAuv3ReadTransport(blockSelf->_hostMusicalContext,
                                    blockSelf->_hostTransportState,
                                    &transport);
        }

        // The plugin's MIDI output goes to the host's block, if it set one.
        BeamerAuv3MidiOutput midiOutput;
        midiOutput.block = blockSelf->_hostMidiOutput;
        midiOutput.bufferStart = (AUEventSampleTime)timestamp->mSampleTime;
        BOOL sendsMidi = (outputBusNumber == 0 && midiOutput.block != nil);

        return beamer_au_render(
            rustInstance,
            actionFlags,
            timestamp,
            frameCount,
            outputBusNumber,
            outputData,
            realtimeEventListHead,
            pullInputBlock,
            inputData,
            hasTransport ? &transport : NULL,
            sendsMidi ? BeamerAuv3SendMidi : NULL,
            sendsMidi ? &midiOutput : NULL
        );
    };

    return _cachedInternalRenderBlock;
}

- (AUParameterTree*)parameterTree {
    if (_parameterTree == nil) {
        [self buildParameterTree];
    }
    return _parameterTree;
}

- (void)buildParameterTree {
    if (_rustInstance == NULL) {
        _parameterTree = nil;
        return;
    }

    uint32_t paramCount = beamer_au_get_parameter_count(_rustInstance);
    uint32_t groupCount = beamer_au_get_group_count(_rustInstance);

    if (paramCount == 0) {
        _parameterTree = [AUParameterTree createTreeWithChildren:@[]];
        return;
    }

    NSMutableArray<NSDictionary*>* allParams = [[NSMutableArray alloc] initWithCapacity:paramCount];
    for (uint32_t i = 0; i < paramCount; i++) {
        BeamerAuParameterInfo info;
        if (!beamer_au_get_parameter_info(_rustInstance, i, &info)) {
            continue;
        }

        NSString* identifier = [NSString stringWithFormat:@"param_%u", info.id];
        NSString* name = [NSString stringWithUTF8String:info.name];
        AudioUnitParameterUnit auUnit = (AudioUnitParameterUnit)info.unit_type;

        AudioUnitParameterOptions flags = kAudioUnitParameterFlag_IsReadable;
        if (!(info.flags & BeamerAuParameterFlagReadOnly)) {
            flags |= kAudioUnitParameterFlag_IsWritable;
        }

        NSArray<NSString*>* valueStrings = nil;
        uint32_t valueCount = beamer_au_get_parameter_value_count(_rustInstance, info.id);
        if (valueCount > 0) {
            NSMutableArray<NSString*>* strings = [[NSMutableArray alloc] initWithCapacity:valueCount];
            char stringBuffer[128];
            for (uint32_t vi = 0; vi < valueCount; vi++) {
                if (beamer_au_get_parameter_value_string(_rustInstance, info.id, vi, stringBuffer, sizeof(stringBuffer))) {
                    [strings addObject:[NSString stringWithUTF8String:stringBuffer]];
                }
            }
            if (strings.count == valueCount) {
                valueStrings = strings;
            }
        }

        // The range from Rust is in AU format: actual values, or an index
        // (0..step_count) for indexed parameters.
        AUParameter* param = [AUParameterTree createParameterWithIdentifier:identifier
                                                                       name:name
                                                                    address:(AUParameterAddress)info.id
                                                                        min:info.min_value
                                                                        max:info.max_value
                                                                       unit:auUnit
                                                                   unitName:nil
                                                                      flags:flags
                                                               valueStrings:valueStrings
                                                        dependentParameters:nil];
        param.value = info.default_value;

        [allParams addObject:@{
            @"param": param,
            @"groupId": @(info.group_id)
        }];
    }

    NSMutableDictionary<NSNumber*, NSDictionary*>* groupInfoMap = [[NSMutableDictionary alloc] init];
    for (uint32_t i = 1; i < groupCount; i++) {
        BeamerAuGroupInfo ginfo;
        if (beamer_au_get_group_info(_rustInstance, i, &ginfo)) {
            NSString* gname = [NSString stringWithUTF8String:ginfo.name];
            groupInfoMap[@(ginfo.id)] = @{
                @"name": gname,
                @"parentId": @(ginfo.parent_id)
            };
        }
    }

    NSMutableDictionary<NSNumber*, AUParameterGroup*>* groupNodes = [[NSMutableDictionary alloc] init];
    NSMutableDictionary<NSNumber*, NSMutableArray<AUParameterNode*>*>* groupChildren = [[NSMutableDictionary alloc] init];

    groupChildren[@0] = [[NSMutableArray alloc] init];
    for (NSNumber* gid in groupInfoMap) {
        groupChildren[gid] = [[NSMutableArray alloc] init];
    }

    for (NSDictionary* pdict in allParams) {
        NSNumber* gid = pdict[@"groupId"];
        NSMutableArray* children = groupChildren[gid];
        if (children == nil) {
            children = groupChildren[@0];
        }
        [children addObject:pdict[@"param"]];
    }

    NSMutableSet<NSNumber*>* remaining = [NSMutableSet setWithArray:groupInfoMap.allKeys];
    while (remaining.count > 0) {
        BOOL madeProgress = NO;
        for (NSNumber* gid in [remaining copy]) {
            NSDictionary* ginfo = groupInfoMap[gid];
            NSNumber* parentId = ginfo[@"parentId"];

            if ([parentId intValue] == 0 || groupNodes[parentId] != nil) {
                NSString* gname = ginfo[@"name"];
                NSString* gidentifier = [NSString stringWithFormat:@"group_%d", [gid intValue]];

                AUParameterGroup* group = [AUParameterTree createGroupWithIdentifier:gidentifier
                                                                                name:gname
                                                                            children:groupChildren[gid]];
                groupNodes[gid] = group;
                [groupChildren[parentId] addObject:group];

                [remaining removeObject:gid];
                madeProgress = YES;
            }
        }

        if (!madeProgress && remaining.count > 0) {
            for (NSNumber* gid in remaining) {
                NSDictionary* ginfo = groupInfoMap[gid];
                NSString* gname = ginfo[@"name"];
                NSString* gidentifier = [NSString stringWithFormat:@"group_%d", [gid intValue]];

                AUParameterGroup* group = [AUParameterTree createGroupWithIdentifier:gidentifier
                                                                                name:gname
                                                                            children:groupChildren[gid]];
                groupNodes[gid] = group;
                [groupChildren[@0] addObject:group];
            }
            break;
        }
    }

    _parameterTree = [AUParameterTree createTreeWithChildren:groupChildren[@0]];
    [self setupParameterCallbacks];
}

- (void)setupParameterCallbacks {
    if (_parameterTree == nil || _rustInstance == NULL) {
        return;
    }

    __weak typeof(self) weakSelf = self;

    _parameterTree.implementorValueProvider = ^AUValue(AUParameter* param) {
        __strong typeof(self) strongSelf = weakSelf;
        if (strongSelf == nil) {
            return 0.0f;
        }

        [strongSelf->_instanceLock lock];
        AUValue result = 0.0f;
        if (strongSelf->_instanceValid && strongSelf->_rustInstance != NULL) {
            result = beamer_au_get_parameter_value_au(strongSelf->_rustInstance, (uint32_t)param.address);
        }
        [strongSelf->_instanceLock unlock];
        return result;
    };

    _parameterTree.implementorValueObserver = ^(AUParameter* param, AUValue value) {
        __strong typeof(self) strongSelf = weakSelf;
        if (strongSelf == nil) {
            return;
        }
        // Skip when the change originated from the webview. The Rust
        // store already has the precise f64 value; writing the f32
        // AUValue back would introduce round-trip artifacts.
        if (strongSelf->_settingFromWebView) {
            return;
        }

        [strongSelf->_instanceLock lock];
        if (strongSelf->_instanceValid && strongSelf->_rustInstance != NULL) {
            beamer_au_set_parameter_value_au(strongSelf->_rustInstance, (uint32_t)param.address, value);
        }
        [strongSelf->_instanceLock unlock];
    };

    _parameterTree.implementorStringFromValueCallback = ^NSString* _Nonnull(AUParameter* param, const AUValue* value) {
        __strong typeof(self) strongSelf = weakSelf;
        AUValue displayValue = (value != NULL) ? *value : param.value;

        if (strongSelf == nil) {
            return [NSString stringWithFormat:@"%.2f", displayValue];
        }

        [strongSelf->_instanceLock lock];
        NSString* result = nil;
        if (strongSelf->_instanceValid && strongSelf->_rustInstance != NULL) {
            // Pass the AU value directly to Rust which normalizes in f64
            // precision, avoiding f32 round-trip artifacts in display strings.
            char buffer[128];
            uint32_t written = beamer_au_format_parameter_value(
                strongSelf->_rustInstance,
                (uint32_t)param.address,
                displayValue,
                buffer,
                sizeof(buffer)
            );
            if (written > 0) {
                result = [NSString stringWithUTF8String:buffer];
            }
        }
        [strongSelf->_instanceLock unlock];

        return (result != nil) ? result : [NSString stringWithFormat:@"%.2f", displayValue];
    };

    _parameterTree.implementorValueFromStringCallback = ^AUValue(AUParameter* param, NSString* string) {
        __strong typeof(self) strongSelf = weakSelf;
        if (strongSelf == nil || string == nil) {
            return param.value;
        }

        [strongSelf->_instanceLock lock];
        AUValue result = param.value;
        if (strongSelf->_instanceValid && strongSelf->_rustInstance != NULL) {
            // Rust parses to AU format: the plain value, or the index for an
            // indexed parameter.
            float parsedValue = 0.0f;
            if (beamer_au_parse_parameter_value(strongSelf->_rustInstance, (uint32_t)param.address, string.UTF8String, &parsedValue)) {
                result = parsedValue;
            }
        }
        [strongSelf->_instanceLock unlock];
        return result;
    };
}

- (NSDictionary<NSString*, id>*)fullState {
    NSMutableDictionary* state = [[super fullState] mutableCopy];
    if (state == nil) {
        state = [[NSMutableDictionary alloc] init];
    }

    if (_rustInstance != NULL) {
        uint32_t stateSize = 0;
        uint8_t* buffer = beamer_au_copy_state(_rustInstance, &stateSize);
        if (buffer != NULL) {
            state[@"beamerState"] = [NSData dataWithBytes:buffer length:stateSize];
            beamer_au_free_state(buffer, stateSize);
        }
    }

    return state;
}

- (void)setFullState:(NSDictionary<NSString*, id>*)fullState {
    [super setFullState:fullState];

    if (_rustInstance != NULL && fullState != nil) {
        NSData* stateData = fullState[@"beamerState"];
        if (stateData != nil && stateData.length > 0) {
            OSStatus status = beamer_au_set_state(_rustInstance, stateData.bytes, (uint32_t)stateData.length);

            if (status != noErr) {
                return;
            }

            if (_parameterTree != nil) {
                for (AUParameter* param in _parameterTree.allParameters) {
                    AUValue newValue = beamer_au_get_parameter_value_au(_rustInstance, (uint32_t)param.address);
                    [param setValue:newValue originator:nil];
                }
            }
        }
    }
}

- (AUAudioUnitPreset*)currentPreset {
    return _currentPreset;
}

- (void)setCurrentPreset:(AUAudioUnitPreset*)currentPreset {
    if (currentPreset == nil) {
        _currentPreset = nil;
        return;
    }
    _currentPreset = currentPreset;

    if (currentPreset.number >= 0) {
        [self applyFactoryPreset:(int)currentPreset.number];
    }
}

- (void)applyFactoryPreset:(int)presetNumber {
    if (_rustInstance == NULL) {
        return;
    }

    if (!beamer_au_apply_preset(_rustInstance, (uint32_t)presetNumber)) {
        return;
    }

    if (_parameterTree != nil) {
        for (AUParameter* param in _parameterTree.allParameters) {
            AUValue newValue = beamer_au_get_parameter_value_au(_rustInstance, (uint32_t)param.address);
            [param setValue:newValue originator:nil];
        }
    }
}

- (NSArray<AUAudioUnitPreset*>*)factoryPresets {
    if (_factoryPresets == nil && _rustInstance != NULL) {
        uint32_t presetCount = beamer_au_get_preset_count(_rustInstance);

        if (presetCount > 0) {
            NSMutableArray<AUAudioUnitPreset*>* presets = [[NSMutableArray alloc] initWithCapacity:presetCount];

            for (uint32_t i = 0; i < presetCount; i++) {
                BeamerAuPresetInfo info;
                memset(&info, 0, sizeof(info));

                if (beamer_au_get_preset_info(_rustInstance, i, &info)) {
                    AUAudioUnitPreset* preset = [[AUAudioUnitPreset alloc] init];
                    preset.number = (NSInteger)info.number;
                    preset.name = [NSString stringWithUTF8String:info.name];
                    [presets addObject:preset];
                }
            }

            _factoryPresets = [presets copy];
        }
    }
    return _factoryPresets;
}

- (NSTimeInterval)latency {
    if (_rustInstance == NULL || _sampleRate <= 0.0) {
        return 0.0;
    }
    uint32_t latencySamples = beamer_au_get_latency_samples(_rustInstance);
    return (NSTimeInterval)latencySamples / _sampleRate;
}

- (NSTimeInterval)tailTime {
    if (_rustInstance == NULL || _sampleRate <= 0.0) {
        return 0.0;
    }
    uint32_t tailSamples = beamer_au_get_tail_samples(_rustInstance);
    if (tailSamples == UINT32_MAX) {
        return INFINITY;
    }
    return (NSTimeInterval)tailSamples / _sampleRate;
}

- (BOOL)supportsMPE {
    return NO;
}

- (NSArray<NSString*>*)MIDIOutputNames {
    // One output for the plugin types that can produce MIDI. The host then
    // sets MIDIOutputEventBlock to receive it.
    if (_rustInstance != NULL && beamer_au_produces_midi(_rustInstance)) {
        return @[@"MIDI Out"];
    }
    return @[];
}

- (BOOL)supportsUserPresets {
    return YES;
}

- (NSArray<NSNumber*>*)channelCapabilities {
    BeamerAuChannelCapabilities caps;
    if (!beamer_au_get_channel_capabilities(_rustInstance, &caps)) {
        return nil;
    }

    if (caps.count == 0) {
        return nil;
    }

    NSMutableArray<NSNumber*>* result = [[NSMutableArray alloc] initWithCapacity:caps.count * 2];
    for (uint32_t i = 0; i < caps.count; i++) {
        [result addObject:@(caps.capabilities[i].input_channels)];
        [result addObject:@(caps.capabilities[i].output_channels)];
    }
    return result;
}

- (void)reset {
    if (_rustInstance != NULL) {
        beamer_au_reset(_rustInstance);
    }
}

- (BOOL)canProcessInPlace {
    return NO;
}

// =============================================================================
// MARK: - View Configuration
// =============================================================================

// Prefer zero-sized view configurations so Logic and GarageBand defer to
// preferredContentSize. If no {0, 0} entry exists (Reaper, other hosts),
// accept all configurations so the host knows we have a GUI.
- (NSIndexSet*)supportedViewConfigurations:(NSArray<AUAudioUnitViewConfiguration*>*)availableViewConfigurations {
    NSMutableIndexSet* zeroSized = [[NSMutableIndexSet alloc] init];
    for (NSUInteger i = 0; i < availableViewConfigurations.count; i++) {
        AUAudioUnitViewConfiguration* config = availableViewConfigurations[i];
        if (config.width + config.height == 0) {
            [zeroSized addIndex:i];
        }
    }
    if ([zeroSized count] > 0) {
        return zeroSized;
    }
    // No {0, 0} entry - accept all so the host shows the GUI.
    return [NSIndexSet indexSetWithIndexesInRange:
        NSMakeRange(0, availableViewConfigurations.count)];
}

// =============================================================================
// MARK: - GUI / WebView
// =============================================================================

// Hosts call this method on the AUAudioUnit to get a view controller for the
// plugin UI. This is the primary UI path for hosts like Reaper that use the
// AUAudioUnit API directly. For hosts that check the extension's principal
// class (Logic Pro), the AUViewController extension in auv3_extension_gui.m
// provides the UI independently.
- (void)requestViewControllerWithCompletionHandler:
    (void (^)(NSViewController* _Nullable))completionHandler {
    if (!beamer_au_has_gui(_rustInstance)) {
        completionHandler(nil);
        return;
    }

    // A new editor replaces the previous one if the host calls this method
    // again.
    [self _closeEditor];
    _editorView = NULL;
    _editorVisible = NO;
    // A teardown of the previous editor that still waits is no longer due.
    _editorHideCount++;

    uint32_t width = 0, height = 0;
    beamer_au_get_gui_size(_rustInstance, &width, &height);

    {{WRAPPER_CLASS}}EditorView* container = [[{{WRAPPER_CLASS}}EditorView alloc]
        initWithFrame:NSMakeRect(0, 0, width, height)];
    {{WRAPPER_CLASS}}EditorController* vc = [[{{WRAPPER_CLASS}}EditorController alloc] init];
    vc.view = container;
    vc.preferredContentSize = NSMakeSize(width, height);

    // Create the WebView right away, so that its content loads before the
    // host shows the view.
    if (![self _openEditorIn:container]) {
        completionHandler(nil);
        return;
    }
    _editorView = (__bridge const void*)container;
    container.wrapper = self;
    vc.wrapper = self;

    completionHandler(vc);
}

// Create the WebView of the editor in `container` and start following the
// plugin: its parameter values and the events it emits.
- (BOOL)_openEditorIn:(NSView*)container {
#ifdef DEBUG
    bool devTools = true;
#else
    bool devTools = false;
#endif

    uint8_t bgColor[4];
    beamer_au_get_gui_background_color(bgColor);

    const char* devUrl = beamer_au_get_gui_url(_rustInstance);
    void* webviewHandle;
    if (devUrl != NULL) {
        webviewHandle = beamer_webview_create_url_with_ipc(
            (__bridge void*)container, devUrl, devTools, bgColor,
            beamer_auv3_on_message, beamer_auv3_on_loaded,
            (__bridge void*)self);
    } else {
        const void* assets = beamer_au_get_gui_assets();
        webviewHandle = beamer_webview_create_with_ipc(
            (__bridge void*)container, assets, devTools, bgColor,
            beamer_auv3_on_message, beamer_auv3_on_loaded,
            (__bridge void*)self);
    }
    if (webviewHandle == NULL) {
        return NO;
    }

    _webviewHandle = webviewHandle;
    // Fill the container, also when the host placed it away from the origin
    // of its superview before the WebView is built again.
    [self _fitEditorTo:container];

    // The first frame sends every parameter, and events the plugin emits
    // from now on are kept for this editor.
    _sync = beamer_au_editor_sync_open(_rustInstance);

    // Start 60 Hz parameter sync timer.
    // Use __weak to avoid a retain cycle (self -> _syncTimer -> block -> self).
    __weak typeof(self) weakSelf = self;
    _syncTimer = [NSTimer timerWithTimeInterval:1.0/60.0 repeats:YES block:^(NSTimer* t) {
        (void)t;
        [weakSelf _sendFrame];
    }];
    // Schedule in the common modes, so that the UI keeps following the host
    // while it runs a tracking loop (a drag, a resize or an open menu).
    [[NSRunLoop currentRunLoop] addTimer:_syncTimer forMode:NSRunLoopCommonModes];
    return YES;
}

// Stop following the plugin and remove the WebView of the editor: the sync
// timer and the editor sync first, then the WebView.
- (void)_closeEditor {
    [_syncTimer invalidate];
    _syncTimer = nil;
    beamer_au_ipc_close_sync(&_sync);
    if (_webviewHandle != NULL) {
        beamer_webview_destroy(_webviewHandle);
        _webviewHandle = NULL;
    }
}

// The view of the editor entered a window: build the WebView again if
// -_editorHidden: removed it.
- (void)_editorShown:(NSView*)view {
    if ((__bridge const void*)view != _editorView) {
        return;
    }
    _editorVisible = YES;
    if (_webviewHandle == NULL) {
        [self _openEditorIn:view];
    }
}

// The view of the editor left its window or the window was hidden. Nothing
// runs for it until it is shown again. The teardown waits for the next turn
// of the run loop: a host that moves the view to another window takes it
// out of one and puts it into the other right away, and the page keeps its
// state then.
- (void)_editorHidden:(NSView*)view {
    if ((__bridge const void*)view != _editorView) {
        return;
    }
    _editorVisible = NO;
    NSUInteger hideCount = ++_editorHideCount;
    __weak typeof(self) weakSelf = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        [weakSelf _closeHiddenEditor:hideCount];
    });
}

// Close the editor if it was not shown again since it was hidden.
- (void)_closeHiddenEditor:(NSUInteger)hideCount {
    if (_editorVisible || hideCount != _editorHideCount) {
        return;
    }
    [self _closeEditor];
}

// The size of the view of the editor changed: the WebView follows it.
- (void)_editorResized:(NSView*)view {
    if ((__bridge const void*)view != _editorView) {
        return;
    }
    [self _fitEditorTo:view];
}

// Give the WebView the bounds of its container.
- (void)_fitEditorTo:(NSView*)container {
    if (_webviewHandle == NULL) {
        return;
    }
    NSSize size = container.bounds.size;
    beamer_webview_set_frame(_webviewHandle, 0, 0, (int32_t)size.width, (int32_t)size.height);
}

// The host let the view of the editor go. Called from the view's dealloc,
// where the view must not be changed: removing the WebView from it could
// keep the view alive past its dealloc. So the timer and the editor sync
// stop now and the WebView is destroyed on the next turn of the run loop.
- (void)_editorGone:(const void*)view {
    if (view != _editorView) {
        return;
    }
    _editorView = NULL;
    void* webviewHandle = _webviewHandle;
    _webviewHandle = NULL;
    [self _closeEditor];
    if (webviewHandle == NULL) {
        return;
    }
    [self _destroyRetiredWebView];
    _retiredWebviewHandle = webviewHandle;
    __weak typeof(self) weakSelf = self;
    dispatch_async(dispatch_get_main_queue(), ^{
        [weakSelf _destroyRetiredWebView];
    });
}

// Destroy the WebView that -_editorGone: retired, if it is still there.
- (void)_destroyRetiredWebView {
    if (_retiredWebviewHandle != NULL) {
        beamer_webview_destroy(_retiredWebviewHandle);
        _retiredWebviewHandle = NULL;
    }
}

@end
